<include file="Public:header"/>	<form id="myform" method="post" action="{pigcms{:U('course_category_edit')}" enctype="multipart/form-data" frame="true" refresh="true">		<input type="hidden" name="id" value="{pigcms{$detail.id}">		<table cellpadding="0" cellspacing="0" class="frame_form" width="100%">			<tr>				<th width="15%">名称</th>				<td width="35%"><input type="text" class="input fl" name="name" id="name" size="25" value="{pigcms{$detail.name}" placeholder="分类名称" validate="maxlength:20,required:true"/></td>			</tr>			<tr>				<th width="15%">排序</th>				<td width="35%"><input type="text" class="input fl" name="sort" id="sort" size="25" value="{pigcms{$detail.sort}" placeholder="排序数字" tips="数字越大越靠前"/></td>			</tr>						<tr>				<th width="15%">是否隐藏</th>				<td width="35%"> 					<span class="cb-enable"><label class="cb-enable <if condition="1 eq $detail['is_hide']">selected</if>"><span>是</span><input type="radio" name="is_hide" value="1" <if condition="1 eq $detail['is_hide']">checked="checked"</if> /></label></span>					<span class="cb-disable"><label class="cb-disable <if condition="1 neq $detail['is_hide']">selected</if>"><span>否</span><input type="radio" name="is_hide" value="0"  <if condition="1 neq $detail['is_hide']">checked="checked" </if>/></label></span>                                    </td>			</tr>			<tr>				<th width="15%">是否热门</th>				<td width="35%">					<span class="cb-enable"><label class="cb-enable <if condition="1 eq $detail['is_popular']">selected</if>"><span>是</span><input type="radio" name="is_popular" value="1" <if condition="1 eq $detail['is_popular']">checked="checked"</if> /></label></span>					<span class="cb-disable"><label class="cb-disable <if condition="1 neq $detail['is_popular']">selected</if>"><span>否</span><input type="radio" name="is_popular" value="0"  <if condition="1 neq $detail['is_popular']">checked="checked" </if>/></label></span>				</td>			</tr>		</table>		<div class="btn hidden">			<input type="submit" name="dosubmit" id="dosubmit" value="提交" class="button" />			<input type="reset" value="取消" class="button" />		</div>	</form><include file="Public:footer"/>